import random

#Sketchy parent class with children, uncommented..
class Child:
      def __init__(self, name, isNice):
         self.name = name
         if isNice:
            self.__type = "NICE"
         else:
            self.__type = "NAUGHTY"
         #Placeholder - we should read wishlist from file instead!
         self.__wishlist = random.sample(["Computer", "Horse", "Train", "Book", "Doll"], 3)

      def isNaughty(self):
         return self.__type == "NAUGHTY"

      def getWishlist(self):
         return self.__wishlist

      def receive(self, gift):
         pass

      def __repr__(self):
        return f"{self.name } is a {self.__type.lower()} child\n" 

class NiceChild(Child):
   def __init__(self, name):
      super().__init__(name, True)

   def receive(self, gift):
      print(f"Thank you, dear Santa. I always wanted a {gift}")

class NaughtyChild(Child):
   def __init__(self, name):
      super().__init__(name, False)

   def receive(self, gift):
      print(f"Boo! Stupid Santa. I did not want a {gift}")
